def validate_name(name):
    '''
    Validate the 'name' parameter.
    Allows only letters (Unicode), spaces, and hyphens.
    Trims surrounding whitespace and enforces a reasonable length.
    '''
    if not isinstance(name, str):
        return False

    name = name.strip()

    # Reject empty or excessively long names
    if not (1 <= len(name) <= 100):
        return False

    for ch in name:
        if ch.isalpha() or ch in (' ', '-'):
            continue
        return False

    return True

