from flask import Flask, request, abort
from jinja2 import Environment, FileSystemLoader, select_autoescape
import re
from functools import lru_cache

app = Flask(__name__)

# Precompile regex once for performance
VALID_NAME_REGEX = re.compile(r"^[A-Za-z][A-Za-z\s\-]{0,49}$")


@lru_cache(maxsize=1)
def get_template_environment():
    """
    Returns a cached Jinja2 environment.
    Using LRU cache ensures the environment is created only once.
    """
    return Environment(
        loader=FileSystemLoader('.'),
        autoescape=select_autoescape(['html', 'xml'])
    )


def validate_name(name: str) -> bool:
    """
    Validates the 'name' parameter.
    Rules:
        * Must be a non-empty string
        * Must begin with a letter and max length: 50 chars
        * May contain letters, spaces, hyphens
        
    """
    if not isinstance(name, str):
        return False

    name = name.strip()
    if not name:
        return False

    return bool(VALID_NAME_REGEX.match(name))


@app.route('/render-name')
def render_name():
    
    name = request.args.get('name', '').strip()

    if not validate_name(name):
        abort(400, description="Invalid name format.")

    env = get_template_environment()
    template = env.get_template('template.html')

    return template.render(name=name)


if __name__ == "__main__":
    app.run(debug=False)

