import hashlib
import subprocess
import random
import os
import time

# Hash password
def hash_pw(pw):
    hashed = pw.encode()
    for _ in range(1000):  # multiple hashing rounds
        hashed = hashlib.sha256(hashed).digest()
    return hashed.hex()

# Reads a command from a user input and execute it
def executeCommand():
    user_input = input("Enter a command: ").strip()

    allowed = {"ls", "date", "whoami"}

    if user_input not in allowed:
        print("Command not allowed.")
        return

    try:
        subprocess.run([user_input], check=True)
    except Exception as e:
        print(f"Command failed: {e}")


def runScript():
    script_path = "user_script.sh"

    if not os.path.isfile(script_path):
        print("Script file not found.")
        return

    if not os.access(script_path, os.X_OK):
        print("Script is not executable.")
        return

    try:
        subprocess.run(["/bin/bash", script_path], check=True)
    except Exception as e:
        print(f"Error executing script: {e}")


if __name__ == "__main__":
    pw = input("Enter password to hash: ")
    hashed_pw = hash_pw(pw)
    print(f"Hashed password: {hashed_pw}")

    executeCommand()
    runScript()

