import hashlib
import subprocess
import os

def hash_pw(pw):
    hashed = pw.encode()
    for _ in range(1000):
        hashed = hashlib.sha256(hashed).digest()
    return hashed.hex()

def executeCommand():
    """SECURE VERSION: Whitelist allowed commands"""
    user_input = input("Enter a command (ls/pwd/date): ")
    
    # Whitelist of allowed commands
    allowed_commands = {
        'ls': ['ls', '-la'],
        'pwd': ['pwd'],
        'date': ['date']
    }
    
    if user_input in allowed_commands:
        # Execute without shell=True for security
        subprocess.run(allowed_commands[user_input])
    else:
        print("Error: Command not allowed. Use: ls, pwd, or date")

def runScript():
    '''
    Reads a shell script from "user_script.sh" and executes it using /bin/bash
    '''
    script_path = "user_script.sh"
    
    if not os.path.isfile(script_path):
        print(f"Error: Script file '{script_path}' not found.")
        return
    
    if not os.access(script_path, os.R_OK):
        print(f"Error: Script file '{script_path}' is not readable.")
        return
    
    try:
        result = subprocess.run(
            ['/bin/bash', script_path],
            capture_output=True,
            text=True,
            timeout=30
        )
        
        if result.stdout:
            print("Script output:", result.stdout)
        if result.stderr:
            print("Script errors:", result.stderr)
        print(f"Exit code: {result.returncode}")
        
    except subprocess.TimeoutExpired:
        print("Error: Script execution timed out.")
    except Exception as e:
        print(f"Error: {e}")

if __name__ == "__main__":
    pw = input("Enter password to hash: ")
    hashed_pw = hash_pw(pw)
    print(f"Hashed password: {hashed_pw}")
    executeCommand()
    runScript()

