import hashlib
import subprocess
import os

def hash_pw(pw):
    hashed = pw.encode()
    # In a real app, use a dedicated library like bcrypt or argon2
    for _ in range(1000):
        hashed = hashlib.sha256(hashed).digest()
    return hashed.hex()

def execute_command_safely():
    """Executes commands without using shell=True to prevent injection."""
    user_input = input("Enter a command (e.g., ls -l): ").split()
    try:
        # We pass a list of arguments instead of a raw string
        subprocess.run(user_input, check=True)
    except Exception as e:
        print(f"Error executing command: {e}")

def run_script():
    """Reads 'user_script.sh' and executes it using /bin/bash."""
    script_path = "user_script.sh"
    if os.path.exists(script_path):
        print(f"Executing {script_path}...")
        subprocess.run(["/bin/bash", script_path])
    else:
        print(f"File {script_path} not found.")

if __name__ == "__main__":
    # 1. Hashing
    pw = input("Enter password to hash: ")
    print(f"Hashed password: {hash_pw(pw)}")

    # 2. Command execution
    execute_command_safely()

    # 3. Running the external script
    run_script()

