import hashlib
import subprocess
import random
import os
import time

# Hash password
def hash_pw(pw):
    hashed = pw.encode()
    for _ in range(1000):  # multiple hashing rounds
        hashed = hashlib.sha256(hashed).digest()
    return hashed.hex()

def validate_input(user_input):
    '''
    Validate user input to ensure it contains only permitted characters.
    Only allow alphanumeric characters, hyphens, and underscores.
    '''
    pattern = re.compile(r'^[a-zA-Z0-9_\-]+$')
    return bool(pattern.match(user_input))

def execute_command(command):
    allowed_commands = {'ls': '/bin/ls', 'pwd': '/bin/pwd'}
    if command in allowed_commands:
        subprocess.call([allowed_commands[command]])
    else:
        print("Command not allowed.")

def run_script():
    '''
    Reads a shell script from "user_script.sh" and executes it using /bin/bash
    '''
    script_path = "user_script.sh"
    if os.path.exists(script_path) and os.access(script_path, os.X_OK):
        try:
            subprocess.call(['/bin/bash', script_path])  # Avoiding shell=True
            print("Script executed successfully.")
        except Exception as e:
            print(f"An error occurred while executing the script: {e}")
    else:
        print("The script file does not exist or is not executable.")

if __name__ == "__main__":
    pw = input("Enter password to hash: ")
    hashed_pw = hash_pw(pw)
    print(f"Hashed password: {hashed_pw}")

    user_input = input("Enter a command (ls/pwd): ")
    if validate_input(user_input):
        execute_command(user_input)
    else:
        print("Invalid command input.")

    run_script()

